/bin/bash -c "python - <<'PY'
import numpy as np
from scipy.ndimage import label
a=np.load('source_pixels.npz')['rgb'].astype(float); med=np.median(a,0); idx=np.abs(a-med[None]).sum(3).argmin(0); bg=a[idx,np.arange(144)[:,None],np.arange(256)[None,:]]
pts={'L':[],'R':[]}
for t in range(26):
 d=np.abs(a[t]-bg).max(2);lab,n=label(d>10)
 for k in range(1,n+1):
  ys,xs=np.where(lab==k)
  if len(xs)<30:continue
  cx,cy=xs.mean(),ys.mean()
  if cx<110 and cy<90:pts['L'].append((t,cx,cy,len(xs)))
  if cx>145 and cy<90:pts['R'].append((t,cx,cy,len(xs)))
for name in pts:
 p=np.array(pts[name]); A=np.c_[np.ones(len(p)),p[:,0]]
 bx=np.linalg.lstsq(A,p[:,1],rcond=None)[0]; by=np.linalg.lstsq(A,p[:,2],rcond=None)[0]
 print(name,'p0',bx[0],by[0],'v',bx[1],by[1],'res',np.sqrt(np.mean((A@bx-p[:,1])**2)),np.sqrt(np.mean((A@by-p[:,2])**2)), 'n',len(p))
 print(p)
PY"
